<?php namespace App\Filament\Resources\ProjectResource\Pages; use App\Filament\Resources\ProjectResource; use Filament\Resources\Pages\CreateRecord; use Illuminate\Support\Facades\Validator; class CreateProject extends CreateRecord {protected static string $resource=ProjectResource::class; protected function mutateFormDataBeforeCreate(array $data):array{$user=auth()->user(); if($user->isSuperAdmin()) Validator::make($data,['company_id'=>['required','integer','exists:companies,id']])->validate(); else $data['company_id']=$user->company_id; $data['status']='planning'; return $data;}}
